import{need,packWorld,pinionParams,packedState,installState}from'./core.js';
export class GPUKernel{
 static async create(){need(globalThis.navigator?.gpu,'WebGPU is unavailable in this browser');const adapter=await navigator.gpu.requestAdapter({powerPreference:'high-performance'});need(adapter,'No WebGPU adapter');need(!adapter.info?.isFallbackAdapter,'Software GPU adapter is not a hardware test');const device=await adapter.requestDevice();return new GPUKernel(adapter,device);}
 constructor(adapter,device){this.adapter=adapter;this.device=device;this.pipelines=new Map;this.layout=device.createBindGroupLayout({entries:Array.from({length:5},(_,binding)=>({binding,visibility:GPUShaderStage.COMPUTE,buffer:{type:[2,3].includes(binding)?'storage':'read-only-storage'}}))});this.pipelineLayout=device.createPipelineLayout({bindGroupLayouts:[this.layout]});device.lost.then(x=>{this.lost=x.message;});}
 async pipeline(role){if(!this.pipelines.has(role)){const response=await fetch(new URL('./'+role+'.wgsl',import.meta.url));need(response.ok,'Shader fetch failed');const code=await response.text(),module=this.device.createShaderModule({code}),messages=await module.getCompilationInfo();need(!messages.messages.some(m=>m.type==='error'),messages.messages.map(m=>m.message).join('\n'));this.pipelines.set(role,await this.device.createComputePipelineAsync({layout:this.pipelineLayout,compute:{module,entryPoint:'main'}}));}return this.pipelines.get(role);}
 get info(){const i=this.adapter.info;return{vendor:i?.vendor??'',architecture:i?.architecture??'',device:i?.device??'',description:i?.description??''};}
 async execute(role,world,bits,states,params,traceWords){const d=this.device;need(!this.lost,this.lost??'Device lost');const pipeline=await this.pipeline(role),arrays=[world,bits,states,new Uint32Array(traceWords),params],buffers=[];for(const a of arrays){need(a.byteLength<=d.limits.maxStorageBufferBindingSize,'Workload exceeds browser storage-buffer limit');const b=d.createBuffer({size:Math.max(4,a.byteLength),usage:GPUBufferUsage.STORAGE|GPUBufferUsage.COPY_DST|GPUBufferUsage.COPY_SRC});if(a.byteLength)d.queue.writeBuffer(b,0,a);buffers.push(b);}const read=d.createBuffer({size:states.byteLength+traceWords*4,usage:GPUBufferUsage.MAP_READ|GPUBufferUsage.COPY_DST});try{const group=d.createBindGroup({layout:pipeline.getBindGroupLayout(0),entries:buffers.map((buffer,binding)=>({binding,resource:{buffer}}))}),enc=d.createCommandEncoder(),pass=enc.beginComputePass();pass.setPipeline(pipeline);pass.setBindGroup(0,group);pass.dispatchWorkgroups(Math.ceil(params[2]/64));pass.end();enc.copyBufferToBuffer(buffers[2],0,read,0,states.byteLength);enc.copyBufferToBuffer(buffers[3],0,read,states.byteLength,traceWords*4);d.queue.submit([enc.finish()]);await read.mapAsync(GPUMapMode.READ);const out=new Uint32Array(read.getMappedRange().slice(0));read.unmap();return{state:out.slice(0,states.length),trace:out.slice(states.length)};}finally{for(const b of buffers)b.destroy();read.destroy();}}
 async pinion(k,jitters){need(jitters.length>0&&jitters.length<=4096&&jitters.every(x=>x===0||x===1),'Invalid GPU batch');const result=await this.execute('pinion',packWorld(k.world),Uint32Array.from(jitters),packedState(k),pinionParams(k,jitters.length),8*jitters.length);installState(k,result.state);return Array.from({length:jitters.length},(_,i)=>Array.from(result.trace.slice(i*8,i*8+8)));}
 async tape(k,steps=128,capacity=4096){need(Number.isInteger(capacity)&&capacity>=8&&capacity<=65536&&Number.isInteger(steps)&&steps>=1&&steps<=4096,'Invalid tape budget');const origin=-Math.floor(capacity/2),program=new Uint32Array(k.states*256*3);for(let i=2;i<program.length;i+=3)program[i]=0xffffffff;for(const[key,[b,d,q]]of k.rules){program.set([b,d>>>0,q],3*key);}const state=new Uint32Array(4+capacity);state.set([k.q,(k.head-origin)>>>0,k.tick,0]);for(const[h,b]of k.cells){need(h>=origin&&h<origin+capacity,'Tape exceeds device window');state[4+h-origin]=b;}const result=await this.execute('tape',program,new Uint32Array(1),state,Uint32Array.from([k.states,steps,1,k.halt,capacity]),4*steps),s=result.state;need(s[3]!==2,'Missing or invalid tape transition');k.q=s[0];k.head=(s[1]|0)+origin;k.tick=s[2];k.status=['ACCEPT','HALT','INVALID','DEFER'][s[3]];k.cells.clear();for(let i=0;i<capacity;i++)if(s[i+4])k.cells.set(i+origin,s[i+4]);return result;}
}
